#[tokio::test]
async fn custody_channel_setup_waits_for_authenticated_wake_acknowledgement() {
    use crate::{discovery::Announce, node::account_devices::AccountDevice};
    use futures_util::FutureExt;
    use std::{net::IpAddr, sync::Arc, time::Duration};
    use tokio::{net::TcpListener, sync::{Semaphore, oneshot}};

    let dir = tempfile::tempdir().unwrap();
    let account = Account::generate();
    let source = node(&dir.path().join("source"), &account);
    let sibling = node(&dir.path().join("sibling"), &account);
    for (owner, peer) in [(&source, &sibling), (&sibling, &source)] {
        owner.account_devices.lock().unwrap().insert(AccountDevice {
            public: peer.identity.public(),
            certificate: account.certify(&peer.identity.public().ed25519_pub),
        }).unwrap();
    }
    let mut hosts = Vec::new();
    for current in [&source, &sibling] {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let observer = if current.user_id() == source.user_id() { &sibling } else { &source };
        observer.roster.lock().unwrap().update(
            &Announce::new_with_account(&current.identity, &account, "wake setup", listener.local_addr().unwrap().port()),
            IpAddr::from([127, 0, 0, 1]), &observer.user_id(),
        );
        hosts.push(crate::node::test_support::IndependentPeerRuntime::start_multithreaded(current.clone(), listener).await);
    }
    let release = Arc::new(Semaphore::new(0));
    let mut observation = CustodySetupObservation::new(&source, &sibling);
    let outcome = std::panic::AssertUnwindSafe(async {
        for host in &mut hosts { host.launch(); }
        let channel = source.create_channel("wake setup", vec![sibling.identity.public()]).await.unwrap();
        observation.mark_channel_created();
        wait_custody_channel_setup(&source, &sibling, channel, &observation).await;
        let (arrived, entered) = oneshot::channel();
        let arrived = Arc::new(std::sync::Mutex::new(Some(arrived)));
        *sibling.account_session_test_hook.lock().unwrap() = Some(Arc::new({
            let exact_source = source.identity.public();
            let release = release.clone();
            move |peer, frame| {
                let exact_source = exact_source.clone();
                let release = release.clone();
                let arrived = arrived.clone();
                Box::pin(async move {
                    if peer == exact_source && matches!(frame, crate::node::account_sync_wire::AccountHistoryFrame::Wake { .. }) {
                        let signal = arrived.lock().unwrap().take();
                        if let Some(signal) = signal { let _ = signal.send(()); }
                        let _ = release.acquire().await;
                    }
                })
            }
        }));
        // Advance the real publisher token without dirtying another document
        // lane. Existing signed heads and Optional settlement remain the old
        // prerequisite while the actual authenticated wake response is held.
        source.note_account_local_change();
        observation.mark_channel_created();
        tokio::time::timeout(Duration::from_secs(5), entered).await.unwrap().unwrap();
        assert!(observation.ready() && observation.optional_ready());
        assert!(custody_linked_capabilities_ready(&source, &sibling));
        assert!(!observation.wake_ready(), "an older authenticated acknowledgement cannot qualify the new publication floor");
        {
            let setup = wait_custody_channel_setup(&source, &sibling, channel, &observation);
            tokio::pin!(setup);
            assert!(futures_util::poll!(setup.as_mut()).is_pending(), "settled document lanes cannot qualify setup while its real wake is unacknowledged");
        }
        release.close();
        wait_custody_channel_setup(&source, &sibling, channel, &observation).await;
        assert!(observation.wake_ready());
    }).catch_unwind().await;
    release.close();
    *sibling.account_session_test_hook.lock().unwrap() = None;
    drop(observation);
    for host in hosts { host.stop().await; }
    if let Err(panic) = outcome { std::panic::resume_unwind(panic); }
}
