            let ready = original_history_received(&receiver, original.clone()).await;
            if ready {
                let imported: HashSet<_> = receiver
                    .account_blocking(move |node| {
                        Ok(node
                            .account_history(&node.account_id(), 20_000)?
                            .into_iter()
                            .map(|row| row.id)
                            .collect())
