                    from: r.from.clone(),
                    wall_clock: r.wall_clock,
                    plaintext: r.plaintext.clone(),
                    event_id: EventId::new(r.event_id),
                })
                .map_err(NodeError::Log)?;
            self.note_account_history_change();
        }
        Ok(())
    }
